if(typeof require==='function'){var Classy=require('./classy');}var InputState=Classy.newClass().name('InputState');InputState.fields({data:{}});InputState.constructor('withState',function(playerId,forward,back,left,right,fire){this.data.playerId=playerId;this.data.forward=forward;this.data.back=back;this.data.left=left;this.data.right=right;this.data.fire=fire;});InputState.constructor('withObject',function(obj){this.data=obj;});InputState.methods({getPlayerId:function(){return this.data.playerId;},getForward:function(){return this.data.forward;},getBack:function(){return this.data.back;},getLeft:function(){return this.data.left;},getRight:function(){return this.data.right;},getFire:function(){return this.data.fire;},toObj:function(){return this.data}});if(typeof module==='object'){module.exports=InputState;}